/// Enqueue one job. Fails only once the worker is gone, which callers already ignore —
/// every trigger site treats delivery as best effort.
pub fn send(
    &self,
    job: NotifyJob,
) -> Result<(), tokio::sync::mpsc::error::SendError<NotifyJob>> {
    // Increment first: a job counted only after a successful send could be drained and
    // decremented before it was ever added, driving the depth negative under load.
    self.depth.bump(1);
    match self.tx.send(job) {
        Ok(()) => Ok(()),
        Err(e) => {
            self.depth.bump(-1);
            Err(e)
        }
    }
}

